@Override
    public boolean canUse() {
        long worldTime = this.seagull.level().getGameTime() % 10;
        if (this.seagull.getNoActionTime() >= 100 && worldTime != 0 || seagull.isSitting() || !AMConfig.seagullStealing) {
            return false;
        }
        if (this.seagull.getRandom().nextInt(12) != 0 && worldTime != 0 || seagull.stealCooldown > 0) {
            return false;
        }
        if(this.seagull.getMainHandItem().isEmpty()){
            Player valid = getClosestValidPlayer();
            if(valid != null){
                target = valid;
                return true;
            }
        }
        return false;
    }

public void start(){
        this.seagull.aiItemFlag = true;
    }

public void stop(){
        this.seagull.aiItemFlag = false;
        target = null;
        fleeVec = null;
        fleeTime = 0;
    }

@Override
    public boolean canContinueToUse() {
        return target != null && !target.isCreative() && (seagull.getMainHandItem().isEmpty() || fleeTime > 0);
    }

public void tick(){
        seagull.setFlying(true);
        seagull.getMoveControl().setWantedPosition(target.getX(), target.getEyeY(), target.getZ(), 1.2F);
        if(seagull.distanceTo(target) < 2F && seagull.getMainHandItem().isEmpty()){
            if(hasFoods(target)){
                ItemStack foodStack = getFoodItemFrom(target);
                if(!foodStack.isEmpty()){
                    ItemStack copy = foodStack.copy();
                    foodStack.shrink(1);
                    copy.setCount(1);
                    seagull.peck();
                    seagull.setItemInHand(InteractionHand.MAIN_HAND, copy);
                    fleeTime = 60;
                    seagull.stealCooldown = 1500 + seagull.getRandom().nextInt(1500);
                    if(target instanceof ServerPlayer){
                        AMAdvancementTriggerRegistry.SEAGULL_STEAL.trigger((ServerPlayer)target);
                    }
                }else{
                    stop();
                }
            }else{
                stop();
            }
        }
        if(fleeTime > 0){
            if(fleeVec == null){
                fleeVec = seagull.getBlockInViewAway(target.position(), 4);
            }
            if(fleeVec != null){
                seagull.setFlying(true);
                seagull.getMoveControl().setWantedPosition(fleeVec.x, fleeVec.y, fleeVec.z, 1.2F);
                if(seagull.distanceToSqr(fleeVec) < 5){
                    fleeVec = seagull.getBlockInViewAway(fleeVec, 4);
                }
            }
            fleeTime--;
        }
    }

private Player getClosestValidPlayer(){
        List<Player> list = seagull.level().getEntitiesOfClass(Player.class, seagull.getBoundingBox().inflate(10, 25, 10), EntitySelector.NO_CREATIVE_OR_SPECTATOR);
        Player closest = null;
        if(!list.isEmpty()){
            for(Player player : list){
                if((closest == null || closest.distanceTo(seagull) > player.distanceTo(seagull)) && hasFoods(player)){
                    closest = player;
                }
            }
        }
        return closest;
    }

private boolean hasFoods(Player player){
        for(int i = 0; i < 9; i++){
            ItemStack stackIn = player.getInventory().items.get(i);
            if(stackIn.isEdible() && !isBlacklisted(stackIn)){
                return true;
            }
        }
        return false;
    }

private ItemStack getFoodItemFrom(Player player){
        List<ItemStack> foods = new ArrayList<>();
        for(int i = 0; i < 9; i++){
            ItemStack stackIn = player.getInventory().items.get(i);
            if(stackIn.isEdible() && !isBlacklisted(stackIn)){
                foods.add(stackIn);
            }
        }
        if(!foods.isEmpty()){
            return foods.get(foods.size() <= 1 ? 0 : seagull.getRandom().nextInt(foods.size() - 1));
        }
        return ItemStack.EMPTY;
    }

private boolean isBlacklisted(ItemStack stack){
        ResourceLocation loc = ForgeRegistries.ITEMS.getKey(stack.getItem());
        if(loc != null){
            for(String str : AMConfig.seagullStealingBlacklist){
                if(loc.toString().equals(str)){
                    return true;
                }
            }
        }
        return false;
    }

public boolean boost(ItemStack stack, LivingEntity entity, int time) {

        if (!entity.getItemBySlot(EquipmentSlot.CHEST).canElytraFly(entity)) {
            return false;
        }
        boolean isPlayer = entity instanceof Player;
        boolean isCreative = isPlayer && ((Player) entity).abilities.instabuild;
        if (!useEnergy(stack, getEnergyPerUse(true) * time / energyUseInterval, isCreative)) {
            return false;
        }
        if (!entity.isFallFlying() && isPlayer) {
            ((Player) entity).startFallFlying();
        }
        propel(entity, propelSpeed);
        stack.getOrCreateTag().putLong(NBTTags.TAG_TIME, entity.level.getGameTime());

        return true;
    }

@Override
    public boolean elytraFlightTick(ItemStack stack, LivingEntity entity, int flightTicks) {

        boolean isCreative = Utils.isCreativePlayer(entity);
        boolean simulate = isCreative || flightTicks % energyUseInterval != 0;
        if (!useEnergy(stack, false, simulate)) {
            return false;
        }

        if (entity.isShiftKeyDown() && useEnergy(stack, true, simulate)) {
            stack.getOrCreateTag().remove(NBTTags.TAG_TIME);
            brake(entity);
        } else {
            CompoundTag tag = stack.getOrCreateTag();
            long time = entity.level.getGameTime();
            if (time - tag.getLong(NBTTags.TAG_TIME) <= boostTime) {
                propel(entity);
            } else if (isEmpowered(stack) && useEnergy(stack, true, isCreative)) {
                tag.putLong(NBTTags.TAG_TIME, time);
                propel(entity);
            }
        }

        return true;
    }

@Override
    public void inventoryTick(ItemStack stack, Level world, Entity entity, int slot, boolean selected) {

        if (entity instanceof LivingEntity && !((LivingEntity) entity).isFallFlying()) {
            stack.getOrCreateTag().remove(NBTTags.TAG_TIME);
        }
    }

@Override
	public void neighborChanged(BlockState state, Level level, BlockPos pos, Block block, BlockPos fromPos,
		boolean isMoving) {
		if (level.isClientSide)
			return;

		Direction blockFacing = state.getValue(FACING);
		if (fromPos.equals(pos.relative(blockFacing.getOpposite()))) {
			if (!canSurvive(state, level, pos)) {
				level.destroyBlock(pos, true);
				return;
			}
		}

		if (!level.getBlockTicks()
			.willTickThisTick(pos, this))
			level.scheduleTick(pos, this, 1);
	}

@Override
	public void tick(BlockState state, ServerLevel level, BlockPos pos, RandomSource r) {
		updateTransmittedSignal(state, level, pos);

		if (state.getValue(RECEIVER))
			return;
		Direction attachedFace = state.getValue(RedstoneLinkBlock.FACING)
			.getOpposite();
		BlockPos attachedPos = pos.relative(attachedFace);
		level.blockUpdated(pos, level.getBlockState(pos)
			.getBlock());
		level.blockUpdated(attachedPos, level.getBlockState(attachedPos)
			.getBlock());
	}

public void updateTransmittedSignal(BlockState state, Level level, BlockPos pos) {
		if (level.isClientSide)
			return;
		if (state.getValue(RECEIVER))
			return;

		int power = getPower(level, state, pos);
		int powerFromPanels = getBlockEntityOptional(level, pos).map(be -> {
			if (be.panelSupport == null)
				return 0;
			Boolean tri = be.panelSupport.shouldBePoweredTristate();
			if (tri == null)
				return -1;
			return tri ? 15 : 0;
		})
			.orElse(0);

		// Suppress update if an input panel exists but is not loaded
		if (powerFromPanels == -1)
			return;

		power = Math.max(power, powerFromPanels);

		boolean previouslyPowered = state.getValue(POWERED);
		if (previouslyPowered != power > 0)
			level.setBlock(pos, state.cycle(POWERED), Block.UPDATE_CLIENTS);

		int transmit = power;
		withBlockEntityDo(level, pos, be -> be.transmit(transmit));
	}

public InteractionResult toggleMode(BlockState state, Level level, BlockPos pos) {
		if (level.isClientSide)
			return InteractionResult.SUCCESS;

		return onBlockEntityUse(level, pos, be -> {
			Boolean wasReceiver = state.getValue(RECEIVER);
			boolean blockPowered = level.hasNeighborSignal(pos);
			level.setBlock(pos, state.cycle(RECEIVER)
				.setValue(POWERED, blockPowered), Block.UPDATE_ALL);
			be.transmit(wasReceiver ? 0 : getPower(level, state, pos));
			return InteractionResult.SUCCESS;
		});
	}

public void setSignal(int power) {
		if (receivedSignal != power)
			receivedSignalChanged = true;
		receivedSignal = power;
	}

public void transmit(int strength) {
		transmittedSignal = strength;
		if (link != null)
			link.notifySignalChange();
	}

@Override
	public void tick() {
		super.tick();

		if (isTransmitterBlock() != transmitter) {
			transmitter = isTransmitterBlock();
			LinkBehaviour prevlink = link;
			removeBehaviour(LinkBehaviour.TYPE);
			createLink();
			link.copyItemsFrom(prevlink);
			attachBehaviourLate(link);
		}

		if (transmitter)
			return;
		if (level.isClientSide)
			return;

		BlockState blockState = getBlockState();
		if (!AllBlocks.REDSTONE_LINK.has(blockState))
			return;

		if ((getReceivedSignal() > 0) != blockState.getValue(RedstoneLinkBlock.POWERED)) {
			receivedSignalChanged = true;
			level.setBlockAndUpdate(worldPosition, blockState.cycle(RedstoneLinkBlock.POWERED));
		}

		if (receivedSignalChanged) {
			updateSelfAndAttached(blockState);
		}
	}

public void updateSelfAndAttached(BlockState blockState) {
		Direction attachedFace = blockState.getValue(RedstoneLinkBlock.FACING)
			.getOpposite();
		BlockPos attachedPos = worldPosition.relative(attachedFace);
		level.blockUpdated(worldPosition, level.getBlockState(worldPosition)
			.getBlock());
		level.blockUpdated(attachedPos, level.getBlockState(attachedPos)
			.getBlock());
		receivedSignalChanged = false;
		panelSupport.notifyPanels();
	}

@Override
	protected void read(CompoundTag compound, HolderLookup.Provider registries, boolean clientPacket) {
		transmitter = compound.getBoolean("Transmitter");
		super.read(compound, registries, clientPacket);

		receivedSignal = compound.getInt("Receive");
		receivedSignalChanged = compound.getBoolean("ReceivedChanged");
		if (level == null || level.isClientSide || !link.newPosition)
			transmittedSignal = compound.getInt("Transmit");
	}

@Override
	public void write(CompoundTag compound, HolderLookup.Provider registries, boolean clientPacket) {
		compound.putBoolean("Transmitter", transmitter);
		compound.putInt("Receive", getReceivedSignal());
		compound.putBoolean("ReceivedChanged", receivedSignalChanged);
		compound.putInt("Transmit", transmittedSignal);
		super.write(compound, registries, clientPacket);
	}

@Override
	protected void checkTickOnNeighbor(Level worldIn, BlockPos pos, BlockState state) {
		boolean back = state.getValue(POWERED);
		boolean shouldBack = shouldTurnOn(worldIn, pos, state);
		boolean side = state.getValue(POWERED_SIDE);
		boolean shouldSide = isPoweredOnSides(worldIn, pos, state);

		TickPriority tickpriority = TickPriority.HIGH;
		if (this.shouldPrioritize(worldIn, pos, state))
			tickpriority = TickPriority.EXTREMELY_HIGH;
		else if (side || back)
			tickpriority = TickPriority.VERY_HIGH;

		if (worldIn.getBlockTicks()
			.willTickThisTick(pos, this))
			return;
		if (back != shouldBack || side != shouldSide)
			worldIn.scheduleTick(pos, this, this.getDelay(state), tickpriority);
	}

@Override
	public void tick(BlockState state, ServerLevel worldIn, BlockPos pos, RandomSource random) {
		boolean back = state.getValue(POWERED);
		boolean shouldBack = this.shouldTurnOn(worldIn, pos, state);
		boolean side = state.getValue(POWERED_SIDE);
		boolean shouldSide = isPoweredOnSides(worldIn, pos, state);
		BlockState stateIn = state;

		if (back != shouldBack) {
			state = state.setValue(POWERED, shouldBack);
			if (shouldBack)
				state = state.setValue(POWERING, true);
			else if (side)
				state = state.setValue(POWERING, false);
		}

		if (side != shouldSide) {
			state = state.setValue(POWERED_SIDE, shouldSide);
			if (shouldSide)
				state = state.setValue(POWERING, false);
			else if (back)
				state = state.setValue(POWERING, true);
		}

		if (state != stateIn)
			worldIn.setBlock(pos, state, Block.UPDATE_CLIENTS);
	}

protected boolean isPoweredOnSides(Level worldIn, BlockPos pos, BlockState state) {
		Direction direction = state.getValue(FACING);
		Direction left = direction.getClockWise();
		Direction right = direction.getCounterClockWise();

		for (Direction d : new Direction[] { left, right }) {
			BlockPos blockpos = pos.relative(d);
			int i = worldIn.getSignal(blockpos, d);
			if (i > 0)
				return true;
			BlockState blockstate = worldIn.getBlockState(blockpos);
			if (blockstate.getBlock() == Blocks.REDSTONE_WIRE && blockstate.getValue(RedStoneWireBlock.POWER) > 0)
				return true;
		}
		return false;
	}

@Override
	protected ItemInteractionResult activated(Level worldIn, BlockPos pos, BlockState state) {
		if (state.getValue(POWERED) != state.getValue(POWERED_SIDE))
			return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;
		if (!worldIn.isClientSide) {
			float f = !state.getValue(POWERING) ? 0.6F : 0.5F;
			worldIn.playSound(null, pos, SoundEvents.LEVER_CLICK, SoundSource.BLOCKS, 0.3F, f);
			worldIn.setBlock(pos, state.cycle(POWERING), Block.UPDATE_CLIENTS);
		}
		return ItemInteractionResult.SUCCESS;
	}

@Override
	protected int getDelay(BlockState state) {
		return 1;
	}

@Override
    public void tickClient(ICommonArmorHandler armorHandler, boolean isEnabled) {
        if (!isEnabled) return;

        trackedPos = PneumaticArmorItem.getCoordTrackerPos(ClientUtils.getWornArmor(EquipmentSlot.HEAD), armorHandler.getPlayer().level());
        worldKey = armorHandler.getPlayer().level().dimension();
        if (trackedPos != null) {
            navigator = new RenderNavigator(trackedPos);
        }
        if (noPathCooldown > 0) {
            noPathCooldown--;
        }
        if (navigator != null && ConfigHelper.client().armor.pathEnabled.get() && noPathCooldown == 0 && --pathCalculateCooldown <= 0) {
            navigator.updatePath();
            if (!navigator.tracedToDestination()) {
                noPathCooldown = 100; // wait 5 seconds before recalculating a path.
            }
            pathCalculateCooldown = ConfigHelper.client().armor.pathUpdateSetting.get().getTicks(); // == 2 ? 1 : pathUpdateSetting == 1 ? 20 : 100;
        }
    }

