@SubscribeEvent
        public static void onPlayerInteract(PlayerInteractEvent.RightClickBlock event) {
            ItemStack helmetStack = event.getEntity().getItemBySlot(EquipmentSlot.HEAD);
            if (!event.getLevel().isClientSide || event.getEntity().getItemBySlot(EquipmentSlot.HEAD).getItem() != ModItems.PNEUMATIC_HELMET.get()) {
                return;
            }
            CommonArmorHandler commonArmorHandler = CommonArmorHandler.getHandlerForPlayer();
            if (commonArmorHandler.getUpgradeCount(EquipmentSlot.HEAD, ModUpgrades.COORDINATE_TRACKER.get()) == 0) return;

            CoordTrackClientHandler handler = ClientArmorRegistry.getInstance()
                    .getClientHandler(CommonUpgradeHandlers.coordTrackerHandler, CoordTrackClientHandler.class);
            if (handler.isListeningToCoordTrackerSetting) {
                handler.isListeningToCoordTrackerSetting = false;
                if (event.getFace() != null) {
                    handler.reset();
                    GlobalPos gPos = GlobalPosHelper.makeGlobalPos(event.getLevel(), event.getPos().relative(event.getFace()));
                    PneumaticArmorItem.setCoordTrackerPos(helmetStack, gPos);

                    PacketUpdateArmorExtraData.sendToServer(CommonUpgradeHandlers.coordTrackerHandler, ModDataComponents.COORD_TRACKER.get(), gPos);

                    HUDHandler.getInstance().addMessage(xlate("pneumaticcraft.armor.gui.coordinateTracker.selectedTarget", PneumaticCraftUtils.posToString(gPos.pos())), Collections.emptyList(), 60, 0x8000AA00);
                }
            }
        }

public static BlockPos getCoordTrackerPos(ItemStack helmetStack, Level world) {
        if (helmetStack.has(ModDataComponents.COORD_TRACKER)) {
            GlobalPos gPos = helmetStack.get(ModDataComponents.COORD_TRACKER);
            if (!world.isOutsideBuildHeight(gPos.pos().getY()) && GlobalPosHelper.isSameWorld(gPos, world)) {
                return helmetStack.get(ModDataComponents.COORD_TRACKER).pos();
            }
        }
        return null;
    }

public static void setCoordTrackerPos(ItemStack helmetStack, GlobalPos gPos) {
        helmetStack.set(ModDataComponents.COORD_TRACKER, gPos);
    }

public InteractionResult useOn(UseOnContext pContext) {
        Level world = pContext.getLevel();
        ItemStack stack = pContext.getItemInHand();
        Player player = pContext.getPlayer();
        if (player != null) {
            if (!stack.isEmpty() && !hasRecall(stack)) {
                CompoundTag compoundTag = stack.getOrCreateTag();
                if (stack.getItem() instanceof RecallFocus) {
                    BlockPos blockpos = pContext.getClickedPos();
                    BlockEntity tileEntity = world.getBlockEntity(blockpos);
                    if (tileEntity instanceof ArcaBlockEntity arcaTile) {
                        if (pContext.getPlayer() == arcaTile.getPlayer() && arcaTile.getLevel() != null) {
                            this.addRecallTags(arcaTile.getLevel().dimension(), arcaTile.getBlockPos(), compoundTag);
                            stack.setTag(compoundTag);
                            player.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                            return InteractionResult.sidedSuccess(world.isClientSide);
                        }
                    }
                    BlockState blockstate = world.getBlockState(blockpos);
                    if (blockstate.is(ModTags.Blocks.RECALL_BLOCKS)) {
                        this.addRecallTags(world.dimension(), blockpos, compoundTag);
                        stack.setTag(compoundTag);
                        player.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                        return InteractionResult.sidedSuccess(world.isClientSide);
                    }
                }
            }
        }
        return InteractionResult.PASS;
    }

public static boolean recall(LivingEntity livingEntity, ItemStack stack){
        if (hasRecall(stack) && stack.getTag() != null) {
            if (getDimension(stack.getTag()).isPresent() && getRecallBlockPos(stack.getTag()) != null) {
                BlockPos blockPos = getRecallBlockPos(stack.getTag());
                if (blockPos != null) {
                    if (getDimension(stack.getTag()).get() == livingEntity.level.dimension()) {
                        Optional<Vec3> optional = RespawnAnchorBlock.findStandUpPosition(EntityType.PLAYER, livingEntity.level, blockPos);
                        if (optional.isPresent()) {
                            net.minecraftforge.event.entity.EntityTeleportEvent.EnderEntity event = net.minecraftforge.event.ForgeEventFactory.onEnderTeleport(livingEntity, optional.get().x, optional.get().y, optional.get().z);
                            if (event.isCanceled()) {
                                return false;
                            }
                            livingEntity.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
                            ModNetwork.INSTANCE.send(PacketDistributor.ALL.noArg(), new SPlayWorldSoundPacket(BlockPos.containing(livingEntity.xo, livingEntity.yo, livingEntity.zo), SoundEvents.ENDERMAN_TELEPORT, 1.0F, 1.0F));
                            ModNetwork.INSTANCE.send(PacketDistributor.ALL.noArg(), new SPlayWorldSoundPacket(BlockPos.containing(optional.get()), SoundEvents.ENDERMAN_TELEPORT, 1.0F, 1.0F));
                            return true;
                        }
                    } else {
                        if (livingEntity.getServer() != null) {
                            ServerLevel serverWorld = livingEntity.getServer().getLevel(getDimension(stack.getTag()).get());
                            if (serverWorld != null) {
                                Optional<Vec3> optional = RespawnAnchorBlock.findStandUpPosition(EntityType.PLAYER, serverWorld, blockPos);
                                if (optional.isPresent()) {
                                    net.minecraftforge.event.entity.EntityTeleportEvent.EnderEntity event = net.minecraftforge.event.ForgeEventFactory.onEnderTeleport(livingEntity, optional.get().x, optional.get().y, optional.get().z);
                                    if (event.isCanceled()) {
                                        return false;
                                    }
                                    livingEntity.changeDimension(serverWorld, new ArcaTeleporter(optional.get()));
                                    livingEntity.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
                                    return true;
                                }
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

public static boolean isValid(ServerLevel serverLevel, ItemStack stack){
        if (hasRecall(stack) && stack.getTag() != null) {
            if (getDimension(stack.getTag()).isPresent()) {
                ServerLevel serverLevel1 = serverLevel.getServer().getLevel(getDimension(stack.getTag()).get());
                if (serverLevel1 != null) {
                    if (getRecallBlockPos(stack.getTag()) != null) {
                        BlockPos blockPos = getRecallBlockPos(stack.getTag());
                        if (blockPos != null) {
                            BlockState blockState = serverLevel1.getBlockState(blockPos);
                            Block block = blockState.getBlock();
                            return block instanceof ArcaBlock || blockState.is(ModTags.Blocks.RECALL_BLOCKS);
                        }
                    }
                }
            }
        }
        return false;
    }

public static boolean hasRecall(ItemStack p_40737_) {
        CompoundTag compoundtag = p_40737_.getTag();
        return compoundtag != null && (compoundtag.contains(TAG_DIMENSION) || compoundtag.contains(TAG_POS));
    }

public static Optional<ResourceKey<Level>> getDimension(CompoundTag p_40728_) {
        return Level.RESOURCE_KEY_CODEC.parse(NbtOps.INSTANCE, p_40728_.get(TAG_DIMENSION)).result();
    }

public void addRecallTags(ResourceKey<Level> p_40733_, BlockPos p_40734_, CompoundTag p_40735_) {
        p_40735_.put(TAG_POS, NbtUtils.writeBlockPos(p_40734_));
        Level.RESOURCE_KEY_CODEC.encodeStart(NbtOps.INSTANCE, p_40733_).resultOrPartial(Goety.LOGGER::error).ifPresent((p_40731_) -> {
            p_40735_.put(TAG_DIMENSION, p_40731_);
        });
    }

public static BlockPos getRecallBlockPos(CompoundTag compoundTag){
        boolean flag = compoundTag.contains(TAG_POS);
        boolean flag1 = compoundTag.contains(TAG_DIMENSION);
        if (flag && flag1) {
            Optional<ResourceKey<Level>> optional = getDimension(compoundTag);
            if (optional.isPresent()) {
                return NbtUtils.readBlockPos(compoundTag.getCompound(TAG_POS));
            }
        }
        return null;
    }

public boolean conditionsMet(ServerLevel worldIn, LivingEntity caster){
        if (caster instanceof ServerPlayer player) {
            if (RecallFocus.isValid(worldIn, WandUtil.findFocus(player))) {
                return true;
            } else if (!RecallFocus.hasRecall(WandUtil.findFocus(player))){
                player.displayClientMessage(Component.translatable("info.goety.focus.noPos"), true);
            } else {
                player.displayClientMessage(Component.translatable("info.goety.focus.PosInvalid"), true);
            }
        }
        return false;
    }

@Override
    public boolean targetConditions(ServerLevel worldIn, LivingEntity caster, @Nullable LivingEntity target, ItemStack staff, SpellStat spellStat) {
        if (caster instanceof ServerPlayer player) {
            if (RecallFocus.isValid(worldIn, WandUtil.findFocus(player))) {
                if (MobUtil.getOwner(target) != null) {
                    return MobUtil.getOwner(target) == caster;
                }
            }
        }
        return false;
    }

@Override
    public void touchResult(ServerLevel worldIn, LivingEntity caster, LivingEntity target, ItemStack staff, SpellStat spellStat) {
        if (caster instanceof ServerPlayer player) {
            if (RecallFocus.isValid(worldIn, WandUtil.findFocus(player))) {
                if (MobUtil.getOwner(target) != null){
                    if (MobUtil.getOwner(target) == caster){
                        if (target instanceof IServant servant) {
                            BlockPos blockPos = RecallFocus.getRecallBlockPos(WandUtil.findFocus(player));
                            servant.setWandering(false);
                            if (blockPos != null) {
                                servant.setStaying(false);
                                servant.setBoundPos(blockPos);
                            } else {
                                servant.setStaying(true);
                                servant.setBoundPos(null);
                            }
                        }
                        if (RecallFocus.recall(target, WandUtil.findFocus(player))) {
                            SEHelper.addSpellCooldown(player, this, (int) (SpellConfig.RecallCoolDown.get() * ModAttributes.getCooldownDiscount(caster)));
                        }
                    }
                }
            }
        }
    }

