public boolean onUsedByWand(Player player, ItemStack stack, Level world, BlockPos pos) {
		if (world.isClientSide) {
			return false;
		}

		if (player == null || player.isShiftKeyDown()) {
			world.destroyBlock(pos, true);
		} else {
			GlobalPos clicked = GlobalPos.of(world.dimension(), pos.immutable());
			if (WandOfTheForestItem.getBindMode(stack)) {
				activeBindingAttempts.put(player.getUUID(), clicked);
				world.playSound(null, pos, BotaniaSounds.ding, SoundSource.BLOCKS, 0.5F, 1F);
			} else {
				var data = WorldData.get(world);
				if (XplatAbstractions.INSTANCE.isDevEnvironment()) {
					BotaniaAPI.LOGGER.info("PistonRelay pairs");
					for (var e : data.mapping.entrySet()) {
						BotaniaAPI.LOGGER.info("{} -> {}", e.getKey(), e.getValue());
					}
				}
				BlockPos dest = data.mapping.get(pos);
				if (dest != null) {
					XplatAbstractions.INSTANCE.sendToNear(world, pos, new BotaniaEffectPacket(EffectType.PARTICLE_BEAM,
							pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5,
							dest.getX(), dest.getY(), dest.getZ()));
				}
			}
		}

		return true;
	}

@Override
	public void onRemove(@NotNull BlockState state, @NotNull Level world, @NotNull BlockPos pos, @NotNull BlockState newState, boolean isMoving) {
		if (!world.isClientSide) {
			var data = WorldData.get(world);

			Direction movementContextDirection = ForcePushHelper.getMovementContextDirection();
			if (isMoving && (movementContextDirection != null || newState.is(Blocks.MOVING_PISTON))) {
				var pistonDirection = movementContextDirection != null
						? movementContextDirection
						: newState.getValue(MovingPistonBlock.FACING);
				// if being moved as part of a retracting sticky piston's block structure, reverse movement direction
				var moveDirection = ForcePushHelper.isExtendingMovementContext() ? pistonDirection : pistonDirection.getOpposite();

				var destPos = data.mapping.get(pos);
				if (destPos != null) {
					BlockPos newSrcPos = pos.relative(moveDirection);

					{
						// Move source side of our binding along
						data.mapping.remove(pos);
						data.mapping.put(newSrcPos, destPos);
						data.setDirty();
					}

					if (!newState.is(Blocks.MOVING_PISTON) || newState.getValue(MovingPistonBlock.TYPE) == PistonType.DEFAULT) {
						// Move the actual bound blocks
						if (ForceLens.moveBlocks(world, destPos.relative(moveDirection.getOpposite()), moveDirection, pos)) {
							// Move dest side of our binding
							data.mapping.put(newSrcPos, data.mapping.get(newSrcPos).relative(moveDirection));
						}
					}
				}
			} else {
				if (data.mapping.remove(pos) != null) {
					data.setDirty();
				}
			}
		}
	}

private static boolean tryCompletePistonRelayBinding(UseOnContext ctx) {
		Level world = ctx.getLevel();
		BlockPos pos = ctx.getClickedPos();
		Player player = ctx.getPlayer();

		GlobalPos bindPos = ((ForceRelayBlock) BotaniaBlocks.pistonRelay).activeBindingAttempts.get(player.getUUID());
		if (bindPos != null && bindPos.dimension() == world.dimension()) {
			((ForceRelayBlock) BotaniaBlocks.pistonRelay).activeBindingAttempts.remove(player.getUUID());
			ForceRelayBlock.WorldData data = ForceRelayBlock.WorldData.get(world);
			data.mapping.put(bindPos.pos(), pos.immutable());
			data.setDirty();

			XplatAbstractions.INSTANCE.sendToNear(world, pos, new BotaniaEffectPacket(EffectType.PARTICLE_BEAM,
					bindPos.pos().getX() + 0.5, bindPos.pos().getY() + 0.5, bindPos.pos().getZ() + 0.5,
					pos.getX(), pos.getY(), pos.getZ()));

			world.playSound(null, player.getX(), player.getY(), player.getZ(), BotaniaSounds.ding, SoundSource.PLAYERS, 1F, 1F);
			return true;
		}
		return false;
	}

public static void onLevelTick(Level level) {
		if(!level.isClientSide()) {
			for(Entity entity : toUpdate.keySet()) {
				if(!entity.hurtMarked) { // Allow velocity change packets to take priority.
					MotionUpdate update = toUpdate.get(entity);
					if(update != null) { // Edge case where the entity expired in the ms between calls
						Vec3 total = update.predicted.add(update.unpredicted);
						//We want a player's motion to be handled client-side to ensure movement consistency
						//Otherwise it feels jerky.
						if(entity instanceof ServerPlayer player) {
							reduceAboveGroundTicks(player, entity);
							if(!update.predicted.equals(Vec3.ZERO)) {
								PsiNetwork.sendToPlayer(player, new MessageAdditiveMotion(entity.getId(), update.predicted.x, update.predicted.y, update.predicted.z, true));
							}
							if(!update.unpredicted.equals(Vec3.ZERO)) {
								PsiNetwork.sendToPlayer(player, new MessageAdditiveMotion(entity.getId(), update.unpredicted.x, update.unpredicted.y, update.unpredicted.z, false));
							}
							reduceAboveGroundTicks(player, entity);
						} else {
							entity.push(total.x, total.y, total.z);
						}
						if(entity.level() instanceof ServerLevel) {
							PsiNetwork.sendToPlayersTracking(entity, new MessageAdditiveMotion(entity.getId(), total.x, total.y, total.z, false));
						}

					}
				}
			}

			toUpdate.clear();
		}
	}

public static void addMotion(Entity entity, double x, double y, double z, boolean predictionEligible) {
		if(x == 0 && y == 0 && z == 0) {
			return;
		}
		Vec3 motion = new Vec3(x, y, z);
		if(entity.level().isClientSide) {
			if(predictionEligible) {
				entity.push(x, y, z);
				PsiClientRuntime.recordPredictedMotion(motion);
			}
		} else {
			MotionUpdate update = toUpdate.getOrDefault(entity, MotionUpdate.EMPTY);
			toUpdate.put(entity, update.add(motion, predictionEligible));
		}
	}

private static void addMotion(SpellContext context, Entity e, Vector3 dir, double speed,
			boolean predicted) throws SpellRuntimeException {
		context.verifyEntity(e);
		if(!context.isInRadius(e)) {
			throw new SpellRuntimeException(SpellRuntimeException.OUTSIDE_RADIUS);
		}

		dir = dir.copy().normalize().multiply(MULTIPLIER * speed);

		if(Math.abs(dir.y) > 0.0001) {
			if(e.getDeltaMovement().y() + dir.y >= 0) {
				e.fallDistance = 0;
			} else if(dir.y > 0) {
				double magicnumber = 25d / 98d; // Equal to 1/terminal velocity of living entity
				double yvel = (e.getDeltaMovement().y() + dir.y) * magicnumber + 1; // inverse % of terminal velocity
				if(yvel > 0) {
					float newfall = (float) (-(49 / magicnumber) + (((49 * yvel) - (Math.log(yvel) / Math.log(4 * magicnumber))) / magicnumber));
					e.fallDistance = Math.min(e.fallDistance, Math.max(0, newfall));
				}
			}
		}

		boolean predictionEligible = predicted && e == context.caster && context.focalPoint == context.caster;
		AdditiveMotionHandler.addMotion(e, dir.x, dir.y, dir.z, predictionEligible);

	}

@Override
	public Object execute(SpellContext context) throws SpellRuntimeException {
		Entity targetVal = this.getParamValue(context, target);
		Vector3 directionVal = this.getParamValue(context, direction);
		double speedVal = this.getParamValue(context, speed).doubleValue();

		addPredictedMotion(context, targetVal, directionVal, speedVal);

		return null;
	}

