public static void recordMotion(Vec3 motion) {
		record(predictedMotion, motion);
	}

public static Vec3 reconcileMotion(Vec3 authoritativeMotion) {
		return reconcile(predictedMotion, authoritativeMotion);
	}

private static void record(Deque<Prediction> predictions, Vec3 value) {
		int tick = currentTick();
		Prediction previous = predictions.peekLast();
		if(previous != null && previous.tick == tick) {
			predictions.removeLast();
			value = previous.value.add(value);
		}
		predictions.addLast(new Prediction(tick, value));
	}

private static Vec3 reconcile(Deque<Prediction> predictions, Vec3 authoritativeValue) {
		int oldestTick = currentTick() - MAX_PREDICTION_AGE;
		while(!predictions.isEmpty() && predictions.peekFirst().tick < oldestTick) {
			predictions.removeFirst();
		}

		Prediction prediction = predictions.pollFirst();
		return prediction == null ? authoritativeValue : authoritativeValue.subtract(prediction.value);
	}

private static int currentTick() {
		return Minecraft.getInstance().player == null ? 0 : Minecraft.getInstance().player.tickCount;
	}

public void activateDeferred() {
		if (cannotLaunch())
			return;
		Direction facing = getFacing();
		List<Entity> entities =
			level.getEntitiesOfClass(Entity.class, new AABB(worldPosition).inflate(-1 / 16f, 0, -1 / 16f));

		// Launch Items
		boolean doLogic = !level.isClientSide || isVirtual();
		if (doLogic)
			launchItems();

		// Launch Entities
		for (Entity entity : entities) {
			boolean isPlayerEntity = entity instanceof Player;
			if (!entity.isAlive())
				continue;
			if (entity instanceof ItemEntity)
				continue;
			if (entity instanceof PackageEntity)
				continue;
			if (entity.getPistonPushReaction() == PushReaction.IGNORE)
				continue;

			entity.setOnGround(false);

			if (isPlayerEntity != level.isClientSide)
				continue;

			entity.setPos(worldPosition.getX() + 0.5, worldPosition.getY() + 1.0, worldPosition.getZ() + 0.5);
			launcher.applyMotion(entity, facing);

			if (!isPlayerEntity)
				continue;

			Player playerEntity = (Player) entity;

			if (launcher.getHorizontalDistance() * launcher.getHorizontalDistance()
				+ launcher.getVerticalDistance() * launcher.getVerticalDistance() >= 25 * 25)
				CatnipServices.NETWORK.sendToServer(new EjectorAwardPacket(worldPosition));

			if (!(playerEntity.getItemBySlot(EquipmentSlot.CHEST)
				.getItem() instanceof ElytraItem))
				continue;

			playerEntity.setXRot(-35);
			playerEntity.setYRot(facing.toYRot());
			playerEntity.setDeltaMovement(playerEntity.getDeltaMovement()
				.scale(.75f));
			deployElytra(playerEntity);
			CatnipServices.NETWORK.sendToServer(new EjectorElytraPacket(worldPosition));
		}

		if (doLogic) {
			lidProgress.chase(1, .8f, Chaser.EXP);
			state = State.LAUNCHING;
			if (!level.isClientSide) {
				level.playSound(null, worldPosition, SoundEvents.WOODEN_TRAPDOOR_CLOSE, SoundSource.BLOCKS, .35f, 1f);
				level.playSound(null, worldPosition, SoundEvents.CHEST_OPEN, SoundSource.BLOCKS, .1f, 1.4f);
			}
		}
	}

